{"title":"Towards Generative Event Factuality Prediction","url":"https://aclanthology.org/2023.findings-acl.44/","doi":"10.18653/v1/2023.findings-acl.44","authors":["John Murzaku","Tyler Osborne","Amittai Aviram","Owen Rambow"],"year":2023,"abstract":"Introduces an end-to-end generative formulation that predicts factuality holders, factuality targets, and associated factuality values rather than assuming only the document author as source. Experiments use all sources and targets represented in FactBank and explore multitask learning with other factuality corpora.","venue":"Findings of the Association for Computational Linguistics: ACL 2023"}
{"title":"Neural Models of Factuality","url":"https://arxiv.org/abs/1804.02472","arxiv_id":"1804.02472","doi":"10.18653/v1/N18-1067","authors":["Rachel Rudinger","Aaron Steven White","Benjamin Van Durme"],"year":2018,"abstract":"Presents neural models for event factuality prediction and evaluates them on FactBank, UW, MEANTIME, and an expanded Universal Decompositional Semantics factuality dataset. It provides component evidence for determining whether textual events are presented as having occurred.","venue":"NAACL-HLT 2018"}
{"title":"Lexicosyntactic Inference in Neural Models","url":"https://arxiv.org/abs/1808.06232","arxiv_id":"1808.06232","doi":"10.18653/v1/D18-1501","authors":["Aaron Steven White","Rachel Rudinger","Kyle Rawlins","Benjamin Van Durme"],"year":2018,"abstract":"Uses event factuality prediction to study inferences created by interactions between lexical items and syntactic contexts. It introduces factuality judgments for English clause-embedding verbs across syntactic environments and exposes systematic errors in neural models.","venue":"EMNLP 2018"}
{"title":"Graph based Neural Networks for Event Factuality Prediction using Syntactic and Semantic Structures","url":"https://arxiv.org/abs/1907.03227","arxiv_id":"1907.03227","doi":"10.18653/v1/P19-1432","authors":["Amir Pouran Ben Veyseh","Thien Huu Nguyen","Dejing Dou"],"year":2019,"abstract":"Models event factuality using graph-based neural networks that combine syntactic and semantic sentence structures. The work addresses sentence-level assessment of whether an event is presented as having happened.","venue":"ACL 2019"}
{"title":"He Thinks He Knows Better than the Doctors: BERT for Event Factuality Fails on Pragmatics","url":"https://arxiv.org/abs/2107.00807","arxiv_id":"2107.00807","doi":"10.1162/tacl_a_00414","authors":["Nanjiang Jiang","Marie-Catherine de Marneffe"],"year":2021,"abstract":"Evaluates BERT-based factuality prediction across multiple English datasets and shows that high aggregate performance can rely on surface regularities. The models remain unreliable on examples requiring pragmatic reasoning, illustrating limitations of static factuality classification.","venue":"Transactions of the Association for Computational Linguistics"}
{"title":"Does It Happen? Multi-hop Path Structures for Event Factuality Prediction with Graph Transformer Networks","url":"https://aclanthology.org/2021.wnut-1.6/","doi":"10.18653/v1/2021.wnut-1.6","authors":["Duong Le","Thien Huu Nguyen"],"year":2021,"abstract":"Introduces an event-factuality model that explicitly represents multi-hop syntactic and semantic paths between words rather than only direct graph connections. Experiments test whether richer sentence structure improves assessment of an event's factual degree.","venue":"W-NUT 2021"}
{"title":"Modality and Negation in Event Extraction","url":"https://arxiv.org/abs/2109.09393","arxiv_id":"2109.09393","doi":"10.18653/v1/2021.case-1.6","authors":["Sander Bijl de Vroe","Liane Guillou","Miloš Stanojević","Nick McKenna","Mark Steedman"],"year":2021,"abstract":"Presents an open-domain event extraction system that explicitly captures modality and negation so that possible, intended, or otherwise non-actual events are not automatically interpreted as having occurred. It supplies component semantics for distinguishing actual events from modal alternatives.","venue":"CASE 2021"}
{"title":"Document-Level Event Factuality Identification Using Negation and Speculation Scope","url":"https://doi.org/10.1007/978-3-030-92185-9_34","doi":"10.1007/978-3-030-92185-9_34","authors":["Heng Zhang","Zhong Qian","Xiaoxu Zhu","Peifeng Li"],"year":2021,"abstract":"Studies document-level event factuality identification using information about negation and speculation scope. It extends factuality assessment beyond isolated local cues, while remaining primarily a factuality component rather than a longitudinal state model.","venue":"Neural Information Processing"}
{"title":"Toward Consistent and Informative Event-Event Temporal Relation Extraction","url":"https://aclanthology.org/2023.matching-1.3/","doi":"10.18653/v1/2023.matching-1.3","authors":["Xiaomeng Jin","Haoyang Wen","Xinya Du","Heng Ji"],"year":2023,"abstract":"Constructs temporal event graphs while explicitly addressing global inconsistency, semantically irrelevant links, and lack of neighborhood context. The method combines pretrained language representations with graph neural modeling and constraints intended to produce globally consistent temporal orderings.","venue":"MATCHING 2023"}
{"title":"Joint Constrained Learning for Event-Event Relation Extraction","url":"https://arxiv.org/abs/2010.06727","arxiv_id":"2010.06727","doi":"10.18653/v1/2020.emnlp-main.51","authors":["Haoyu Wang","Muhao Chen","Hongming Zhang","Dan Roth"],"year":2020,"abstract":"Jointly models temporal and subevent relations among event mentions and converts logical constraints across those relations into differentiable learning objectives. The resulting event complexes encode temporal ordering and event-membership structure with cross-relation consistency.","venue":"EMNLP 2020"}
{"title":"Global Inference to Chinese Temporal Relation Extraction","url":"https://aclanthology.org/C16-1137/","authors":["Peifeng Li","Qiaoming Zhu","Guodong Zhou","Hongling Wang"],"year":2016,"abstract":"Introduces discourse-level global inference for temporal relations between event mentions, including relations spanning nonadjacent sentences. Semantic constraints are used to improve coherence of document-level temporal interpretation.","venue":"COLING 2016"}
{"title":"Domain Knowledge Empowered Structured Neural Net for End-to-End Event Temporal Relation Extraction","url":"https://arxiv.org/abs/2009.07373","arxiv_id":"2009.07373","doi":"10.18653/v1/2020.emnlp-main.461","authors":["Rujun Han","Yichao Zhou","Nanyun Peng"],"year":2020,"abstract":"Combines neural temporal-relation extraction with probabilistic domain constraints and structured inference. Lagrangian relaxation is used to incorporate distributional constraints rather than assuming that all structural knowledge is an infallible hard rule.","venue":"EMNLP 2020"}
{"title":"Clinical Temporal Relation Extraction with Probabilistic Soft Logic Regularization and Global Inference","url":"https://doi.org/10.1609/aaai.v35i16.17721","doi":"10.1609/aaai.v35i16.17721","authors":["Yichao Zhou","Yu Yan","Rujun Han","J. Harry Caufield","Kai-Wei Chang","Yizhou Sun","Peipei Ping","Wei Wang"],"year":2021,"published":"2021-05-18","abstract":"Performs document-level extraction of temporal relations among clinical events using probabilistic soft logic regularization and global inference. It explicitly models global relational dependencies rather than classifying event pairs independently.","venue":"AAAI 2021"}
{"title":"Beyond Pairwise: Global Zero-shot Temporal Graph Generation","url":"https://arxiv.org/abs/2502.11114","arxiv_id":"2502.11114","doi":"10.18653/v1/2025.emnlp-main.1601","authors":["Alon Eirew","Kfir Bar","Ido Dagan"],"year":2025,"abstract":"Generates a document's complete temporal graph in a single zero-shot step and then applies temporal constraint optimization to enforce consistency among relations. It also introduces OmniTemp, with complete temporal annotations for targeted event pairs within documents.","venue":"EMNLP 2025"}
{"title":"TimeML: Robust Specification of Event and Temporal Expressions in Text","url":"https://aaai.org/papers/0005-ss03-07-005-timeml-robust-specification-of-event-and-temporal-expressions-in-text/","authors":["James Pustejovsky","José Castaño","Robert Ingria","Roser Saurí","Robert Gaizauskas","Andrea Setzer","Graham Katz","Dragomir Radev"],"year":2003,"abstract":"Defines a temporal annotation language that anchors event predicates to temporal expressions and orders events relative to one another both within sentences and across discourse. The representation also covers underspecified temporal expressions, aspectual predication, and modal subordination.","venue":"New Directions in Question Answering, Papers from the 2003 AAAI Spring Symposium"}
{"title":"Maintaining knowledge about temporal intervals","url":"https://doi.org/10.1145/182.358434","doi":"10.1145/182.358434","authors":["James F. Allen"],"year":1983,"abstract":"Introduces interval-based temporal reasoning and a constraint-propagation procedure for maintaining relations among temporal intervals. The resulting interval algebra provides a foundational representation for reasoning about ordering, overlap, containment, and other temporal relationships.","venue":"Communications of the ACM"}
{"title":"A Taxonomy of Time in Databases","url":"https://doi.org/10.1145/318898.318921","doi":"10.1145/318898.318921","authors":["Richard Snodgrass","Ilsoo Ahn"],"year":1985,"abstract":"Proposes a taxonomy of three distinct notions of time for databases and argues that supporting all of them is necessary to capture time-varying behavior without conflating different temporal semantics. The work is foundational for separating when facts hold from when their representations are stored or otherwise temporally situated.","venue":"ACM SIGMOD 1985"}
{"title":"A Consensus Glossary of Temporal Database Concepts","url":"https://doi.org/10.1145/181550.181560","doi":"10.1145/181550.181560","authors":["Christian S. Jensen","James Clifford","Ramez Elmasri","Shashi K. Gadia","Pat Hayes","Sushil Jajodia","Curtis Dyreson","Fabio Grandi","Wolfgang Käfer","Nick Kline","Nikos Lorentzos","Yannis Mitsopoulos","Angelo Montanari","Daniel Nonen","Elisa Peressi","Barbara Pernici","John F. Roddick","Nandlal L. Sarda","Maria Rita Scalas","Arie Segev","Richard T. Snodgrass","Mike D. Soo","Abdullah Tansel","Paolo Tiberio","Gio Wiederhold"],"year":1994,"abstract":"Standardizes definitions for temporal-database concepts and explains distinctions among temporal notions used by the database community. It provides representation vocabulary relevant to valid time, transaction time, bitemporal information, and preservation of historical database states.","venue":"ACM SIGMOD Record"}
{"title":"Resolution of time concepts in temporal databases","url":"https://doi.org/10.1016/0020-0255(94)90059-0","doi":"10.1016/0020-0255(94)90059-0","authors":["Sharma Chakravarthy","Seung-Kyum Kim"],"year":1994,"abstract":"Distinguishes event time, valid time, and transaction time and analyzes their roles in precise preservation of temporal information. The paper argues that event time is needed for retroactive and proactive updates and shows how multiple time dimensions preserve past states through error corrections, delayed updates, and other changes.","venue":"Information Sciences"}
{"title":"Semantics of time-varying information","url":"https://doi.org/10.1016/0306-4379(96)00017-8","doi":"10.1016/0306-4379(96)00017-8","authors":["Christian S. Jensen","Richard T. Snodgrass"],"year":1996,"abstract":"Provides a systematic semantic treatment of temporal database facts associated with valid time and transaction time. It examines bitemporal relations and how multiple temporal dimensions preserve and expose different states of time-varying information.","venue":"Information Systems"}
{"title":"A truth maintenance system","url":"https://doi.org/10.1016/0004-3702(79)90008-0","doi":"10.1016/0004-3702(79)90008-0","authors":["Jon Doyle"],"year":1979,"abstract":"Introduces the Truth Maintenance System, which records reasons for beliefs and revises the current belief set when discoveries contradict assumptions. It supports dependency-directed backtracking, explanations, alternative belief systems, and revision of models of other agents' beliefs.","venue":"Artificial Intelligence"}
{"title":"An assumption-based TMS","url":"https://doi.org/10.1016/0004-3702(86)90080-9","doi":"10.1016/0004-3702(86)90080-9","authors":["Johan de Kleer"],"year":1986,"abstract":"Introduces an assumption-based truth-maintenance architecture that records assumption sets rather than maintaining only individual justifications. This permits reasoning with inconsistent information, inexpensive context switching, and simultaneous exploration of alternative solutions while preserving their dependency structure.","venue":"Artificial Intelligence"}
{"title":"On the logic of theory change: Partial meet contraction and revision functions","url":"https://doi.org/10.2307/2274239","doi":"10.2307/2274239","authors":["Carlos E. Alchourrón","Peter Gärdenfors","David Makinson"],"year":1985,"abstract":"Formalizes contraction and revision of belief theories and develops partial-meet contraction functions with representation results for rationality postulates. It is foundational to belief revision under newly introduced or withdrawn propositions.","venue":"The Journal of Symbolic Logic"}
{"title":"On the logic of iterated belief revision","url":"https://doi.org/10.1016/S0004-3702(96)00038-0","doi":"10.1016/S0004-3702(96)00038-0","authors":["Adnan Darwiche","Judea Pearl"],"year":1997,"abstract":"Shows that the standard AGM postulates are insufficient for rational sequences of revisions because they do not adequately preserve conditional beliefs across successive observations. It adds postulates for iterated revision and represents revision as transformation of richer epistemic states.","venue":"Artificial Intelligence"}
{"title":"On the difference between updating a knowledge base and revising it","url":"https://doi.org/10.1017/CBO9780511526664.007","doi":"10.1017/CBO9780511526664.007","authors":["Hirofumi Katsuno","Alberto O. Mendelzon"],"year":1992,"abstract":"Distinguishes revision, where new information changes beliefs about a static world, from update, where the represented world itself has changed. The distinction is directly relevant to separating corrections of prior assessments from genuine event or work-item state transitions.","venue":"Belief Revision"}
{"title":"Agreement, Disputes and Commitments in Dialogue","url":"https://doi.org/10.1093/jos/ffn013","doi":"10.1093/jos/ffn013","authors":["Alex Lascarides","Nicholas Asher"],"year":2009,"published":"2009-02-06","abstract":"Provides a formal analysis of dialogue in which each participant has public commitments, including commitments to rhetorical or relational speech acts such as Correction. Agreement is defined through shared entailments, while the framework also gives consistent interpretations to disputes and to what remains agreed after disagreement.","venue":"Journal of Semantics"}
{"title":"The Problem of Retraction in Critical Discussion","url":"https://doi.org/10.1023/A:1010318403544","doi":"10.1023/A:1010318403544","authors":["Erik C. W. Krabbe"],"year":2001,"abstract":"Examines how dialogue models should permit reasonable retraction of commitments while constraining disruptive withdrawals. The analysis treats retraction as necessary both for resolving disputes and for repairing inconsistencies that have been exposed during dialogue.","venue":"Synthese"}
{"title":"Layered message semantics using social commitments","url":"https://doi.org/10.1145/1082473.1082754","doi":"10.1145/1082473.1082754","authors":["Roberto A. Flores","Philippe Pasquier","Brahim Chaib-draa"],"year":2005,"abstract":"Defines agent messages as coordinating devices that advance conversations, social commitments, and joint activities. Its commitment model includes lifecycle states such as accepted, rejected, active, fulfilled, violated, inactive, and cancelled, with messages interpreted partly through the commitment-state transitions they induce.","venue":"AAMAS 2005"}
{"title":"Why and Where: A Characterization of Data Provenance","url":"https://doi.org/10.1007/3-540-44503-X_20","doi":"10.1007/3-540-44503-X_20","authors":["Peter Buneman","Sanjeev Khanna","Wang-Chiew Tan"],"year":2001,"abstract":"Formalizes provenance for data created through database queries and distinguishes why-provenance, identifying source data that influenced an output, from where-provenance, identifying source locations from which output values originated. The distinction supplies foundational machinery for retaining evidential lineage instead of only final values.","venue":"ICDT 2001"}
{"title":"Provenance Semirings","url":"https://doi.org/10.1145/1265530.1265535","doi":"10.1145/1265530.1265535","authors":["Todd J. Green","Grigoris Karvounarakis","Val Tannen"],"year":2007,"abstract":"Develops a general provenance representation based on semirings of polynomials, unifying several earlier database semantics including why-provenance. The framework records how output facts are derived from underlying inputs rather than retaining only their resulting values.","venue":"PODS 2007"}
{"title":"An Empirical Characterization of Event Sourced Systems and Their Schema Evolution -- Lessons from Industry","url":"https://arxiv.org/abs/2104.01146","arxiv_id":"2104.01146","doi":"10.1016/j.jss.2021.110970","authors":["Michiel Overeem","Marten Spoor","Slinger Jansen","Sjaak Brinkkemper"],"year":2021,"abstract":"Empirically studies event-sourced systems and how practitioners preserve and evolve event histories. It identifies schema-evolution strategies including versioned events, weak schemas, upcasting, in-place transformation, and copy-and-transform, providing engineering evidence for immutable history and state reconstruction.","venue":"Journal of Systems and Software"}
{"title":"Identifying Semantic Edit Intentions from Revisions in Wikipedia","url":"https://aclanthology.org/D17-1213/","doi":"10.18653/v1/D17-1213","authors":["Diyi Yang","Aaron Halfaker","Robert Kraut","Eduard Hovy"],"year":2017,"abstract":"Develops a taxonomy of semantic intentions underlying Wikipedia revisions rather than treating edits only as surface operations, and trains a classifier to identify those intentions. The work supplies transfer evidence for distinguishing semantically different kinds of document change.","venue":"EMNLP 2017"}
{"title":"Making Revisions Understandable: A Survey of Edit Intentions, Methods, and Applications","url":"https://arxiv.org/abs/2609.01610","arxiv_id":"2609.01610","doi":"10.18653/v1/2026.findings-acl.1747","authors":["Fangping Lan","Qi Zhang","Eduard Dragut"],"year":2026,"abstract":"Surveys NLP research on revision histories through the lens of edit intentions, covering revision corpora, intent taxonomies, identification methods, and applications. It is useful for locating work that differentiates the semantic purposes of revisions rather than merely detecting textual differences.","venue":"Findings of the Association for Computational Linguistics: ACL 2026"}
{"title":"The nature of requests and commitments in email messages","url":"https://researchers.mq.edu.au/en/publications/the-nature-of-requests-and-commitments-in-email-messages/","authors":["Andrew Lampert","Robert Dale","Cécile Paris"],"year":2008,"abstract":"Studies task-oriented requests and commitments in workplace email and defines them at utterance level rather than only classifying whole messages. The work is motivated by tracking outstanding promises and unmet requests and reports annotation experiments on Enron email, providing workplace-specific component evidence even though it does not itself implement full longitudinal state tracking.","venue":"Papers from the 2008 AAAI Workshop"}
{"title":"Two strategies of reopening QUDs— evidence from German auch & noch","url":"https://ojs.ub.uni-konstanz.de/sub/index.php/sub/article/view/152","authors":["Mira Grubic"],"year":2019,"abstract":"Analyzes explicit reopening of a Question under Discussion so that further true answers can be added. It distinguishes reopening with a different resource situation from reopening with a different topic situation, providing linguistic transfer evidence for reopening unresolved or previously addressed issues.","venue":"Proceedings of Sinn und Bedeutung"}
{"title":"Discourse integration guided by the ‘Question under Discussion’","url":"https://doi.org/10.1016/j.cogpsych.2012.04.001","doi":"10.1016/j.cogpsych.2012.04.001","authors":["Charles Clifton Jr.","Lyn Frazier"],"year":2012,"abstract":"Reports experiments showing that discourse processing is facilitated when subsequent material addresses an explicit or implicit Question under Discussion and disrupted when an implicit QUD remains unresolved. The experiments include QUDs triggered by non-actuality expressions such as intentions and obligations.","venue":"Cognitive Psychology"}
{"title":"Annotation guidelines for Questions under Discussion and information structure","url":"https://doi.org/10.1075/slcs.199.14rie","doi":"10.1075/slcs.199.14rie","authors":["Arndt Riester","Lisa Brunetti","Kordula De Kuthy"],"year":2018,"published":"2018-08-02","abstract":"Presents a meaning-based method for annotating implicit Questions under Discussion in naturally occurring written and spoken discourse. The guidelines derive QUDs from surrounding discourse and distinguish asserted, focused, backgrounded, and non-at-issue material.","venue":"Information Structure in Lesser-described Languages"}
{"title":"TSVer: A Benchmark for Fact Verification Against Time-Series Evidence","url":"https://arxiv.org/abs/2511.01101","arxiv_id":"2511.01101","doi":"10.18653/v1/2025.emnlp-main.1519","authors":["Marek Strong","Andreas Vlachos"],"year":2025,"abstract":"Introduces a benchmark for verifying real-world claims against structured time-series evidence. Claims are paired with relevant temporal ranges, verification verdicts, and evidence-based justifications, making the task useful transfer evidence for separating textual assertions from externally supported temporal verification.","venue":"EMNLP 2025"}
{"title":"HeterMV: Multi-view reasoning over source-aware heterogeneous evidence graph for multi-source fact verification","url":"https://doi.org/10.1016/j.ipm.2026.104709","doi":"10.1016/j.ipm.2026.104709","authors":["Junnan Gu","Weimin Li","Fangfang Liu","Wei Liu","Hao Wang"],"year":2026,"abstract":"Introduces a source-aware heterogeneous evidence graph for multi-source fact verification, representing core evidence, context, and reference documents as distinct node types. Multi-view reasoning includes an explicit corroboration view and consistency learning intended to combine supportive evidence while suppressing noisy or conflicting signals.","venue":"Information Processing & Management"}
